      cert_cloudflare: { t: 'Fix the certificate in Cloudflare', d: 'Cloudflare dashboard → SSL/TLS → Overview: set the mode to Full (strict). Under Edge Certificates check that the universal certificate is active. If your origin has no valid certificate, install a Cloudflare Origin Certificate.' },
      cert_cpanel_autossl: { t: 'Issue the certificate from cPanel', d: 'cPanel → SSL/TLS Status: tick the domain and click "Run AutoSSL". If it fails, check the domain already points to this server and no redirect blocks validation.' },
      cert_plesk: { t: 'Issue the certificate from Plesk', d: 'Plesk → Websites & Domains → SSL/TLS Certificates → "Install a free basic certificate provided by Let\'s Encrypt". Include the www alias too.' },
      cert_plataforma: { t: 'Renew the certificate on your platform', d: 'Your site runs on a managed platform, which issues the certificate. In the domain settings, remove and re-add the custom domain to force re-issuance, and confirm DNS points where their docs say.' },
      cert_iis: { t: 'Issue the certificate on IIS', d: 'Using win-acme (free) on the Windows server, run the command below and choose IIS installation. Schedule the auto-renewal task it offers at the end.' },
      cert_certbot_nginx: { t: 'Issue and renew with Certbot (Nginx)', d: 'Run the command on the server. Then confirm auto-renewal is active with the second command: with 200-day certificates or shorter, manual renewal stops being viable.' },
