      cert_generico: { t: 'Issue a valid certificate', d: 'Install Certbot on the server and issue the certificate including both the www and non-www names. With no server access, ask your host to enable the free certificate for this domain.' },
      cert_reemitir_san: { t: 'Re-issue the certificate including {dominio}', d: 'The current certificate covers: {san}. Re-issue it adding this domain to the list, or redirect this domain to the one that is covered.' },
      cadena_intermedios: { t: 'Serve the full chain', d: 'Configure the server to send the full chain file, not just the leaf certificate. Use the config file below.' },
      redireccion_cloudflare: { t: 'Turn on the redirect in Cloudflare', d: 'Cloudflare → SSL/TLS → Edge Certificates: enable "Always Use HTTPS". Immediate, without touching your server.' },
      redireccion_wordpress: { t: 'Force https in WordPress', d: 'In Settings → General, set both site addresses to https://. Then add the block below at the top of the .htaccess in your web root.' },
      redireccion_nginx: { t: 'Redirect http to https in Nginx', d: 'Add the block below to the site config and reload with "nginx -t && systemctl reload nginx".' },
      redireccion_iis: { t: 'Redirect http to https in IIS', d: 'You need the URL Rewrite module. Add the block to the web.config in the site root.' },
      redireccion_plataforma: { t: 'Turn on the redirect on your platform', d: 'Look for "Force HTTPS" or "SSL redirect" in your platform domain settings. It is a switch, no code needed.' },
      redireccion_apache: { t: 'Redirect http to https in Apache', d: 'Add the block below at the top of the .htaccess file in your web root folder.' },
      hsts_cloudflare: { t: 'Enable HSTS in Cloudflare', d: 'SSL/TLS → Edge Certificates → HTTP Strict Transport Security (HSTS): enable it with a max-age of 6 months or more. First make sure your whole site works over https: HSTS cannot be undone quickly.' },
      hsts_nginx: { t: 'Add HSTS in Nginx', d: 'Add the header below inside the block listening on port 443 and reload the config.' },
      hsts_iis: { t: 'Add HSTS in IIS', d: 'Add the headers block to the site web.config.' },
      hsts_plataforma: { t: 'Enable HSTS on your platform', d: 'Look for the HSTS option in the domain security settings. If there is none, ask their support: only the server can send this header.' },
      hsts_apache: { t: 'Add HSTS in Apache', d: 'Add the block below to .htaccess (requires mod_headers).' },
      mixto_wordpress: { t: 'Remove mixed content in WordPress', d: 'Run the WP-CLI command to replace http URLs with https across the database. Back up first. Detected resources: {ejemplos}.' },
      mixto_generico: { t: 'Remove mixed content', d: 'Switch the resources loaded over http to https (or relative paths). Detected: {ejemplos}. As an immediate patch you can send the header below.' },
      tls_cloudflare: { t: 'Raise the minimum TLS version in Cloudflare', d: 'SSL/TLS → Edge Certificates → Minimum TLS Version: set it to TLS 1.2.' },
      tls_nginx: { t: 'Disable TLS 1.0 and 1.1 in Nginx', d: 'Replace the ssl_protocols directive with the one below and reload the config.' },
      tls_iis: { t: 'Disable TLS 1.0 and 1.1 on Windows', d: 'Use the free IIS Crypto tool (Best Practices) or disable the protocols in the registry under SCHANNEL\\Protocols. Requires a server reboot.' },
      tls_apache: { t: 'Disable TLS 1.0 and 1.1 in Apache', d: 'Put the SSLProtocol directive below in the site SSL config and reload Apache.' },
      variante_www: { t: 'Fix the {variante} variant', d: 'Include both forms (www and non-www) in the same certificate and redirect one to the other. This is the most common failure and the most invisible: you always use the one that works.' },
