      dmarc_alta: { t: 'Publish a DMARC record', d: 'Add the TXT record below. Start at p=none to observe without blocking; after a few weeks of reports, tighten the policy.' },
      dmarc_endurecer: { t: 'Tighten your DMARC policy', d: 'Your current policy only observes. Once reports confirm your legitimate mail passes, move to partial quarantine with the value below.' },
      dkim_alta: { t: 'Enable DKIM signing', d: 'You enable it at your mail provider ({mx}), which gives you the exact record to publish. This is what makes DMARC meaningful.' },
      caa_alta: { t: 'Publish a CAA record', d: 'With this record, only your current authority ({ca}) can issue certificates for your domain.' },
