      cert_certbot_nginx: { t: 'Mit Certbot ausstellen und erneuern (Nginx)', d: 'Führen Sie den Befehl auf dem Server aus. Prüfen Sie danach mit dem zweiten Befehl, ob die automatische Erneuerung aktiv ist: Bei Laufzeiten von 200 Tagen oder weniger ist manuelles Erneuern nicht mehr tragbar.' },
      cert_certbot_apache: { t: 'Mit Certbot ausstellen und erneuern (Apache)', d: 'Führen Sie den Befehl auf dem Server aus. Prüfen Sie danach mit dem zweiten Befehl, ob die automatische Erneuerung aktiv ist.' },
      cert_generico: { t: 'Ein gültiges Zertifikat ausstellen', d: 'Installieren Sie Certbot auf dem Server und stellen Sie das Zertifikat für die Domain mit und ohne www aus. Ohne Serverzugang bitten Sie Ihren Hoster, das kostenlose Zertifikat für diese Domain zu aktivieren.' },
