      redireccion_wordpress: { t: 'https in WordPress erzwingen', d: 'Unter Einstellungen → Allgemein beide Website-Adressen auf https:// setzen. Danach den Block unten an den Anfang der .htaccess im Web-Root einfügen.' },
      redireccion_nginx: { t: 'http auf https umleiten (Nginx)', d: 'Fügen Sie den Block unten zur Site-Konfiguration hinzu und laden Sie mit „nginx -t && systemctl reload nginx" neu.' },
      redireccion_iis: { t: 'http auf https umleiten (IIS)', d: 'Sie brauchen das Modul URL Rewrite. Fügen Sie den Block in die web.config im Site-Root ein.' },
